// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract MostSignificantBit{
    function findMostSinnificantBit(uint256 x) external pure returns (uint8 r){
        if(x > 2 ** 18){
            x >> 128;
            r += 128;
        }

        if(x >= 2 ** 64){
            x >> 64;
            r += 64;
        }

        if(x > 2 ** 32){
            x >> 32;
            r += 32;
        }

        if(x > 2 ** 16){
            x >> 16;
            r += 16;
        }

        if(x > 2 ** 8){
            x >> 8;
            r += 8;
        }

        if(x > 2 ** 4){
            x >> 4;
            r += 4;
        }

        if(x > 2 ** 2){
            x >> 2;
            r += 2;
        }

        if(x > 2 ** 1){
            x >> 1;
            r += 1;
        }
    }
}

